//
//  CountryLookup.swift
//  The offline country lookup for When & where country conditions
//  (docs/conditional-sessions-redesign.md §5.6, §5.7; C5, C9, Q4; C15 step 5).
//
//  - Pure: Foundation only, no CoreLocation, no geocoder, no network. The
//    borders are the bundled `CountryBorders.bin` (Natural Earth admin-0,
//    public domain; source, version and checksums in
//    COUNTRY_BORDERS_ATTRIBUTION.md, generated by
//    Tests/GenerateCountryBorders.py). Nothing here reads or keeps a location:
//    the caller hands in one point and gets one answer back.
//  - The answer is a region code (or none) and how far the point is from the
//    nearest place where the answer could be a different country. The
//    engine's evaluator then adds the fix's accuracy and the 2 km border margin
//    (`ConditionEvaluator.locationResult`); this file never decides "met".
//  - Coastlines aren't borders: sea within `coastBandMeters` of exactly one
//    country counts as that country (a beach whose fix falls just offshore).
//  - Disputed or indeterminate areas without a code in the dataset, and any
//    overlap, answer "no country, 0 m away": "Too close to a border to tell"
//    (Q4). Region names on screen come from iOS, never from the dataset.
//  - Distances are lower bounds (east-west at the most poleward latitude of
//    each edge), so doubt only grows near a border; they are capped at
//    `distanceCapMeters`, which is far beyond any margin.
//  - Every reported distance is shortened by `datasetAllowanceMeters`:
//    Natural Earth's own borders are off by up to about 2 km in places (its
//    Netherlands/Germany/Belgium tripoint sits ~1.9 km from Vaalserberg), so
//    with the engine's 2 km margin a country is told only beyond about
//    3 km + the fix's accuracy from a border. Doubt favours "can't tell".
//

import Foundation

struct CountryBorders {
    /// Dataset entries for areas the dataset gives no region code (Q4).
    static let unidentifiedCode = "~~"
    /// Sea this close to one country's coast counts as that country.
    static let coastBandMeters: Double = 2_000
    /// Distances beyond this are reported as this (conservative: never larger).
    static let distanceCapMeters: Double = 1_000_000
    /// Taken off every reported distance for the dataset's own error.
    static let datasetAllowanceMeters: Double = 1_000
    static let resourceName = "CountryBorders"
    static let resourceExtension = "bin"

    private struct Ring {
        let start: Int
        let end: Int
        let minLon: Double, maxLon: Double, minLat: Double, maxLat: Double
    }

    private struct Entry {
        let code: String
        let rings: [Ring]
    }

    private let entries: [Entry]
    private let lons: [Double]
    private let lats: [Double]

    /// Region codes the dataset can answer with, sorted (never the unidentified entry).
    let regionCodes: [String]

    var pointCount: Int { lons.count }

    /// The bundled borders, read once on first use; nil if the file is missing
    /// or damaged (then a country can't be told: "Couldn't tell which country
    /// you're in", fail closed).
    static let bundled: CountryBorders? = {
        guard let url = Bundle.main.url(forResource: resourceName, withExtension: resourceExtension),
              let data = try? Data(contentsOf: url, options: .mappedIfSafe) else { return nil }
        return CountryBorders(data: data)
    }()

    /// Decodes format version 1 (see Tests/GenerateCountryBorders.py). Any
    /// truncation, bad header or unreasonable count gives nil, never a
    /// partial map.
    init?(data: Data) {
        let bytes = [UInt8](data)
        var offset = 0
        func byte() -> UInt8? {
            guard offset < bytes.count else { return nil }
            defer { offset += 1 }
            return bytes[offset]
        }
        func littleEndian(_ count: Int) -> UInt64? {
            guard offset + count <= bytes.count else { return nil }
            var value: UInt64 = 0
            for i in 0..<count { value |= UInt64(bytes[offset + i]) << (8 * UInt64(i)) }
            offset += count
            return value
        }
        func varint() -> UInt64? {
            var value: UInt64 = 0, shift: UInt64 = 0
            while shift < 64 {
                guard let b = byte() else { return nil }
                value |= UInt64(b & 0x7F) << shift
                if b & 0x80 == 0 { return value }
                shift += 7
            }
            return nil
        }
        func signed() -> Int64? {
            guard let raw = varint() else { return nil }
            return Int64(bitPattern: raw >> 1) ^ -Int64(bitPattern: raw & 1)
        }
        guard bytes.count > 11, Array(bytes[0..<4]) == Array("DMCB".utf8) else { return nil }
        offset = 4
        guard byte() == 1, let units = littleEndian(4), units > 0, units <= 10_000_000,
              let count = littleEndian(2), count > 0 else { return nil }
        let scale = 1 / Double(units)
        var entries: [Entry] = []
        var lons: [Double] = [], lats: [Double] = []
        lons.reserveCapacity(bytes.count / 4)
        lats.reserveCapacity(bytes.count / 4)
        for _ in 0..<count {
            guard let a = byte(), let b = byte(), let ringCount = varint(), ringCount < 100_000 else { return nil }
            let code = String(decoding: [a, b], as: UTF8.self)
            guard code == Self.unidentifiedCode
                    || (code.unicodeScalars.count == 2 && code.unicodeScalars.allSatisfy { (65...90).contains($0.value) })
            else { return nil }
            var rings: [Ring] = []
            for _ in 0..<ringCount {
                guard let points = varint(), points >= 3, points <= UInt64(bytes.count) else { return nil }
                let start = lons.count
                var x: Int64 = 0, y: Int64 = 0
                var minLon = Double.infinity, maxLon = -Double.infinity
                var minLat = Double.infinity, maxLat = -Double.infinity
                for _ in 0..<points {
                    guard let dx = signed(), let dy = signed() else { return nil }
                    x += dx; y += dy
                    let lon = Double(x) * scale, lat = Double(y) * scale
                    guard (-180...180).contains(lon), (-90...90).contains(lat) else { return nil }
                    lons.append(lon); lats.append(lat)
                    minLon = min(minLon, lon); maxLon = max(maxLon, lon)
                    minLat = min(minLat, lat); maxLat = max(maxLat, lat)
                }
                rings.append(Ring(start: start, end: lons.count, minLon: minLon, maxLon: maxLon,
                                  minLat: minLat, maxLat: maxLat))
            }
            entries.append(Entry(code: code, rings: rings))
        }
        guard offset == bytes.count else { return nil }
        self.entries = entries
        self.lons = lons
        self.lats = lats
        regionCodes = Array(Set(entries.map(\.code)).subtracting([Self.unidentifiedCode])).sorted()
    }

    // MARK: Lookup

    /// The country at this point and how far it is from any other country
    /// (or, at sea, from the nearest land). Invalid coordinates → no answer.
    func lookup(latitude: Double, longitude: Double) -> ConditionalCountryLookup? {
        guard let raw = rawLookup(latitude: latitude, longitude: longitude) else { return nil }
        return ConditionalCountryLookup(regionCode: raw.regionCode,
                                        borderDistanceMeters: max(0, raw.borderDistanceMeters - Self.datasetAllowanceMeters))
    }

    /// The same answer with the dataset's own distances (no allowance).
    func rawLookup(latitude: Double, longitude: Double) -> ConditionalCountryLookup? {
        guard latitude.isFinite, longitude.isFinite, (-90...90).contains(latitude),
              (-180...180).contains(longitude) else { return nil }
        var containing: [Int] = []
        var distances = [Double](repeating: Self.distanceCapMeters, count: entries.count)
        for (index, entry) in entries.enumerated() {
            var inside = false
            for ring in entry.rings {
                if contains(ring, latitude: latitude, longitude: longitude) { inside.toggle() }
                distances[index] = min(distances[index],
                                       distance(to: ring, latitude: latitude, longitude: longitude,
                                                below: distances[index]))
            }
            if inside { containing.append(index) }
        }
        func nearestOther(than own: Int) -> Double {
            distances.indices.filter { $0 != own }.map { distances[$0] }.min() ?? Self.distanceCapMeters
        }
        if containing.count > 1 { return ConditionalCountryLookup(regionCode: nil, borderDistanceMeters: 0) }
        if let own = containing.first {
            guard entries[own].code != Self.unidentifiedCode else {
                return ConditionalCountryLookup(regionCode: nil, borderDistanceMeters: 0)
            }
            return ConditionalCountryLookup(regionCode: entries[own].code, borderDistanceMeters: nearestOther(than: own))
        }
        // At sea (or in a coastline's simplification gap).
        guard let nearest = distances.indices.min(by: { distances[$0] < distances[$1] }) else {
            return ConditionalCountryLookup(regionCode: nil, borderDistanceMeters: Self.distanceCapMeters)
        }
        guard distances[nearest] <= Self.coastBandMeters else {
            return ConditionalCountryLookup(regionCode: nil, borderDistanceMeters: distances[nearest])
        }
        guard entries[nearest].code != Self.unidentifiedCode else {
            return ConditionalCountryLookup(regionCode: nil, borderDistanceMeters: 0)
        }
        return ConditionalCountryLookup(regionCode: entries[nearest].code,
                                        borderDistanceMeters: nearestOther(than: nearest))
    }

    /// Even-odd crossing test in longitude/latitude, the plane the dataset's
    /// edges are straight in. Rings never cross ±180° (Natural Earth splits
    /// them there), so no wrapping is needed here.
    private func contains(_ ring: Ring, latitude: Double, longitude: Double) -> Bool {
        guard latitude >= ring.minLat, latitude <= ring.maxLat,
              longitude >= ring.minLon, longitude <= ring.maxLon else { return false }
        var inside = false
        var j = ring.end - 1
        for i in ring.start..<ring.end {
            let yi = lats[i], yj = lats[j]
            if (yi > latitude) != (yj > latitude) {
                let x = lons[i] + (latitude - yi) * (lons[j] - lons[i]) / (yj - yi)
                if longitude < x { inside.toggle() }
            }
            j = i
        }
        return inside
    }

    /// Metres from the point to the ring's edges, never more than the true
    /// distance (within the small-distance approximation), or `below` when
    /// the ring can't be nearer than that.
    private func distance(to ring: Ring, latitude: Double, longitude: Double, below: Double) -> Double {
        let metresPerDegree = Double.pi / 180 * ConditionEvaluator.earthRadius
        let latitudeGap = max(0, ring.minLat - latitude, latitude - ring.maxLat) * metresPerDegree
        guard latitudeGap < below else { return below }
        var best = below
        var j = ring.end - 1
        for i in ring.start..<ring.end {
            let aLat = lats[j], bLat = lats[i]
            let dyA = aLat - latitude, dyB = bLat - latitude
            // Both ends farther north or south than the best so far: skip.
            if min(abs(dyA), abs(dyB)) * metresPerDegree >= best && dyA * dyB > 0 { j = i; continue }
            let poleward = max(abs(latitude), abs(aLat), abs(bLat))
            let scale = cos(poleward * .pi / 180)
            // Unwrapped across ±180°: the edge's own span is always short.
            let ax = Self.wrap(lons[j] - longitude) * scale
            let bx = ax + Self.wrap(lons[i] - lons[j]) * scale
            let dx = bx - ax, dy = dyB - dyA
            let length = dx * dx + dy * dy
            let t = length > 0 ? max(0, min(1, -(ax * dx + dyA * dy) / length)) : 0
            let px = ax + t * dx, py = dyA + t * dy
            best = min(best, (px * px + py * py).squareRoot() * metresPerDegree)
            j = i
        }
        return best
    }

    /// Degrees into -180…180.
    static func wrap(_ degrees: Double) -> Double {
        var value = degrees.truncatingRemainder(dividingBy: 360)
        if value > 180 { value -= 360 }
        if value < -180 { value += 360 }
        return value
    }
}
